menv python - <<'PY'
from hera.analysis import open_run, summarize_run, resolve_channels, current_channel, sdh_onset
import numpy as np
for i in range(8):
 r=open_run(f'data/{i}'); print(summarize_run(r)); print('duration min',(r.meta['end_time']-r.meta['start_time'])/60)
 if i>=5:
  cs=resolve_channels(r.meta); ic=current_channel(cs); vc=[c for c in cs if not c.is_current][0]; I=r.col(ic.col)/ic.gain; R=np.abs(r.col(vc.col)/vc.gain/I)
  print('I nA',np.percentile(I,[0,50,100])*1e9,'R ohm',np.percentile(R,[0,50,100]))
  print('dt seconds',np.percentile(np.diff(r.col('time')),[0,25,50,75,100]))
  print('gate current ranges',[(c,np.percentile(r.col(c),[0,50,100]).tolist()) for c in r.cols if c.endswith('_curr')])
  if i>=6:
   try: print(sdh_onset(R,r.col('magnet_field'),r_full_scale=5000).summary())
   except ValueError as ex: print(type(ex).__name__,str(ex))
PY
